<script>
(function(){
  var form=document.getElementById('filters'), host=document.getElementById('rows'), page=0,size=20,total=0,busy=false,search='';
  var endpoint='<?= base_url('reports/customer_group_sales_data'); ?>', exportBase='<?= base_url('reports/customer_group_sales_export'); ?>';
  var csrfName='<?= $this->security->get_csrf_token_name(); ?>',csrfHash='<?= $this->security->get_csrf_hash(); ?>',currency='<?= htmlspecialchars($CI->currency(),ENT_QUOTES,'UTF-8'); ?>';
  function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c];});}
  function money(v){return currency+' '+Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});}
  function filters(){var p=new URLSearchParams(new FormData(form));p.set('search',search);return p;}
  function setExports(){var p=filters();['csv','excel','pdf'].forEach(function(x){document.getElementById('export-'+x).href=exportBase+'/'+x+'?'+p.toString();});}
  function enhanceSelects(){document.querySelectorAll('select.mp-select').forEach(function(sel){var wrap=document.createElement('div');wrap.className='select-wrap';var trigger=document.createElement('button');trigger.type='button';trigger.className='select-trigger';var options=document.createElement('div');options.className='select-options';function sync(){trigger.textContent=sel.options[sel.selectedIndex]?sel.options[sel.selectedIndex].text:'Choose';options.innerHTML='';Array.prototype.forEach.call(sel.options,function(option){var row=document.createElement('div');row.className='select-option'+(option.selected?' active':'');row.textContent=option.text;row.addEventListener('click',function(){sel.value=option.value;sel.dispatchEvent(new Event('change',{bubbles:true}));sync();wrap.classList.remove('open');});options.appendChild(row);});}sel.parentNode.insertBefore(wrap,sel);wrap.appendChild(sel);wrap.appendChild(trigger);wrap.appendChild(options);trigger.addEventListener('click',function(){wrap.classList.toggle('open');});sel.addEventListener('change',sync);sync();});}
  async function load(){if(busy)return;busy=true;host.innerHTML='<div class="empty">Loading…</div>';var p=filters();p.set('start',String(page*size));p.set('length',String(size));p.set(csrfName,csrfHash);try{var res=await fetch(endpoint,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:p.toString()});var data=await res.json();if(data.csrf_hash)csrfHash=data.csrf_hash;if(!res.ok||!Array.isArray(data.data))throw new Error('Could not load report.');total=Number(data.recordsFiltered||0);document.getElementById('member-total').textContent=money(data.summary.member_sales);document.getElementById('individual-total').textContent=money(data.summary.individual_sales);document.getElementById('retail-total').textContent=money(data.summary.retail_sales);document.getElementById('all-total').textContent=money(data.summary.total_sales);document.getElementById('count').textContent='('+total.toLocaleString()+' lines)';host.innerHTML=data.data.length?data.data.map(function(r){var member=r.pricing_source==='group',individual=r.pricing_source==='customer',type=member?'Member':(individual?'Individual adjustment':'Retail');return '<article class="line"><div class="line-head"><div><div class="line-title">'+esc(r.item_name)+'</div><div class="line-meta"><a href="<?= base_url('sales/invoice/'); ?>'+encodeURIComponent(r.sale_id)+'">'+esc(r.sales_code)+'</a> · '+esc(r.sales_date)+'<br>'+esc(r.customer_name||'Walk-in')+' · '+esc(r.warehouse_name||'')+'</div></div><div class="line-amount">'+money(r.line_total)+'</div></div><div class="line-meta">Qty '+esc(r.qty)+' · Unit '+money(r.unit_price)+' · <span class="badge '+(member?'':(individual?'retail':'retail'))+'">'+type+'</span> '+(member?esc(r.pricing_group_name||'Member group'):'')+'</div></article>';}).join(''):'<div class="empty">No sales match these filters.</div>';var pages=Math.max(1,Math.ceil(total/size));document.getElementById('page-status').textContent='Page '+(page+1)+' of '+pages;document.getElementById('prev').disabled=page<=0;document.getElementById('next').disabled=(page+1)*size>=total;setExports();}catch(e){host.innerHTML='<div class="empty">'+esc(e.message)+'</div>';}finally{busy=false;}}
  form.addEventListener('submit',function(e){e.preventDefault();page=0;load();});document.getElementById('prev').addEventListener('click',function(){if(page>0){page--;load();}});document.getElementById('next').addEventListener('click',function(){if((page+1)*size<total){page++;load();}});document.getElementById('reset').addEventListener('click',function(){form.reset();document.getElementById('report-search').value='';search='';page=0;load();});var timer;document.getElementById('report-search').addEventListener('input',function(){search=this.value.trim();clearTimeout(timer);timer=setTimeout(function(){page=0;load();},350);});enhanceSelects();setExports();load();
})();
</script>
